/* =====================================================================
   StitchFlow ERP v2 — Garment Manufacturing for D2C (Myntra)
   Modules: PO → Inward → Job Work (fabric + trims to job-worker vendor,
            multi-style FG received) → Sale, plus Reports
            (GRN / issues / WIP / FG received / stock) and Masters.
   Premium UI: every dropdown is a searchable combobox.
   Data persists in localStorage (in-memory fallback for sandboxed preview).
   ===================================================================== */

/* ---- visible error diagnostics: never a silent blank page ---- */
function showErr(msg, stack) {
  var el = document.getElementById('jsErr');
  if (el) {
    el.style.display = 'block';
    var detail = stack ? '<span style="font-weight:400;opacity:.85"> — ' + esc(stack.split('\n').slice(0, 3).join(' → ')) + '</span>' : '';
    el.innerHTML += '<div>• ' + esc(msg) + detail + '</div>';
  }
}
function isForeignScript(src) {
  if (!src) return false;
  // ignore errors injected by browser extensions or third-party CDN beacons
  return /^(chrome|moz|safari)-extension:/.test(src) ||
         (/^https?:/.test(src) && src.indexOf(location.origin) !== 0);
}
window.onerror = function (msg, src, line, col, err) {
  if (isForeignScript(src)) return false;   // not our code — stay quiet
  showErr(msg + ' (line ' + line + ')', err && err.stack);
  return false;
};
window.addEventListener('unhandledrejection', function (e) { showErr('Promise error: ' + (e.reason && e.reason.message ? e.reason.message : e.reason)); });

/* ---------------- Helpers ---------------- */
const $  = (id) => document.getElementById(id);
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtNum = (n) => (Number(n) || 0).toLocaleString('en-IN', {maximumFractionDigits: 2});
const fmtInventoryNum = (n) => Math.round(Number(n) || 0).toLocaleString('en-IN');
const fmtINR = (n) => '₹' + fmtNum(n);
const pf = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const today = () => { const d = new Date(); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); };
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
const sumBy = (arr, k) => (arr || []).reduce((a, i) => a + pf(i[k]), 0);
const sumItemAmt = (arr) => (arr || []).reduce((a, i) => a + pf(i.qty) * pf(i.rate), 0);
function qsa(sel, root) { root = root || document; return root.querySelectorAll ? Array.prototype.slice.call(root.querySelectorAll(sel)) : []; }
function qs(sel, root) { root = root || document; return root.querySelector ? root.querySelector(sel) : null; }

function badge(st) {
  const map = {
    'Draft':'b-gray','Approved':'b-blue','Partially Received':'b-amber','Received':'b-green','Closed':'b-gray','Cancelled':'b-red',
    'Rejected':'b-red','Completed':'b-green',
    'Issued':'b-blue','In Progress':'b-pink','Quality Check':'b-amber',
    'Open':'b-blue','In Progress':'b-amber','Packed':'b-green',
    'Loaded':'b-blue','In Transit':'b-amber','Delivered':'b-green','Returned':'b-red',
    'Unpaid':'b-red','Paid':'b-green','Partial':'b-amber'
  };
  return '<span class="badge ' + (map[st] || 'b-gray') + '">' + esc(st) + '</span>';
}
/* A process type always receives the same colour throughout the listings.
   Standard processes have fixed business colours; custom Master values use
   a deterministic palette so their colour remains stable between sessions. */
function processTypeBadge(type) {
  const label = String(type || '—').trim() || '—';
  const key = label.toLowerCase();
  const fixed = { washing:'b-yellow', embroidery:'b-blue', printing:'b-purple' };
  let tone = fixed[key];
  if (!tone) {
    const palette = ['b-teal','b-amber','b-pink','b-green','b-purple','b-blue'];
    let hash = 0;
    for (let i = 0; i < key.length; i++) hash = ((hash * 31) + key.charCodeAt(i)) >>> 0;
    tone = palette[hash % palette.length];
  }
  return '<span class="badge ' + tone + '">' + esc(label) + '</span>';
}

/* =====================================================================
   REQUIRED-FIELD HIGHLIGHTING
   Every save routine calls clearReqMarks() first, then returns
   reqBad(target, message) instead of a bare toast — the offending field
   is outlined red, its label flagged, scrolled into view and focused.
   ===================================================================== */
function reqResolve(target) {
  if (!target) return null;
  if (target.nodeType === 1) return target;                     /* already an element */
  const s = String(target);
  /* a searchable combobox / multiselect registered under this id */
  const cb = qs('[data-cb-input="' + s + '"]') || qs('[data-mcb-input="' + s + '"]');
  if (cb) return cb;
  const el = document.getElementById(s);
  if (el) return el;
  return qs(s.charAt(0) === '#' || s.charAt(0) === '.' ? s : '#' + s);
}
function clearReqMarks(root) {
  const r = root || document;
  qsa('.inp-bad', r).forEach(function (el) { el.classList.remove('inp-bad'); });
  qsa('.cbox-bad', r).forEach(function (el) { el.classList.remove('cbox-bad'); });
  qsa('.field-bad', r).forEach(function (el) { el.classList.remove('field-bad'); });
  qsa('.cell-bad', r).forEach(function (el) { el.classList.remove('cell-bad'); });
}
/* mark a field invalid — returns false so callers can `return reqBad(...)` */
function reqBad(target, msg) {
  const el = reqResolve(target);
  if (el) {
    const box = el.closest ? (el.closest('.cbox') || el.closest('.mcbox')) : null;
    if (box) box.classList.add('cbox-bad'); else el.classList.add('inp-bad');
    const fld = el.closest ? el.closest('.field') : null;
    if (fld) fld.classList.add('field-bad');
    const td = el.closest ? el.closest('td') : null;
    if (td) td.classList.add('cell-bad');
    const scrollTo = fld || td || box || el;
    try { scrollTo.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (e) {}
    const flashEl = box || el;
    flashEl.classList.remove('req-flash');
    void flashEl.offsetWidth;
    flashEl.classList.add('req-flash');
    setTimeout(function () { flashEl.classList.remove('req-flash'); }, 600);
    setTimeout(function () {
      try { (box ? qs('.cbox-input,.mcbox-input', box) : el).focus({ preventScroll: true }); } catch (e) {}
    }, 220);
  }
  if (msg) toast(msg, 'red');
  return false;
}
/* highlight a cell inside a mini-table row (item grids) */
function reqBadCell(tbodyId, rowIndex, fieldName, msg) {
  const rows = qsa('#' + tbodyId + ' tr');
  const tr = rows[rowIndex] || rows[0];
  let el = null;
  if (tr) el = qs('[data-f="' + fieldName + '"]', tr) || qs('.inp', tr);
  return reqBad(el, msg);
}
/* value stored in a row cell — resolves comboboxes, multiselects and inputs */
function rowVal(tr, f) {
  const el = qs('[data-f="' + f + '"]', tr);
  if (!el) return '';
  if (el.dataset.cbInput) return String(cboxGet(el.dataset.cbInput) || '').trim();
  if (el.dataset.cb) return String(cboxGet(el.dataset.cb) || '').trim();
  return String(el.value || '').trim();
}
/* sizes picked in a row's multiselect */
function rowSizes(tr) {
  const mb = qs('.mcbox', tr);
  if (!mb || !mb.dataset.mcb) return [];
  const c = MCBOX[mb.dataset.mcb];
  return c ? c.sel.slice() : [];
}
/* true when the row carries no user data at all (a spare blank line) */
function rowIsBlank(tr, fields) {
  const anyField = (fields || []).some(function (f) { return rowVal(tr, f) !== ''; });
  if (anyField) return false;
  if (rowSizes(tr).length) return false;
  return true;
}
/* highlight a named cell inside a specific row element */
function reqBadIn(tr, f, msg) {
  let el = qs('[data-f="' + f + '"]', tr);
  if (!el && f === '__sizes') el = qs('.mcbox-input', tr);
  return reqBad(el || qs('.inp', tr), msg);
}
/* Validate mandatory cells on every non-blank row of a mini-table.
   specs: [{ f:'name', label:'Item Name' }, ...]  ('__sizes' = the multiselect)
   Returns true when everything is fine. */
function requireRowFields(tbodyId, specs, rowNoun) {
  const rows = qsa('#' + tbodyId + ' tr');
  const scan = specs.map(function (s) { return s.f; }).filter(function (f) { return f !== '__sizes'; });
  let filled = 0;
  for (let i = 0; i < rows.length; i++) {
    const tr = rows[i];
    if (rowIsBlank(tr, scan)) continue;
    filled++;
    for (let k = 0; k < specs.length; k++) {
      const sp = specs[k];
      const empty = (sp.f === '__sizes') ? !rowSizes(tr).length : rowVal(tr, sp.f) === '';
      if (empty) {
        reqBadIn(tr, sp.f, sp.label + ' is required on ' + (rowNoun || 'row') + ' ' + (i + 1));
        return false;
      }
    }
  }
  if (!filled) {
    const first = rows[0];
    if (first) reqBadIn(first, specs[0].f, specs[0].label + ' is required — complete at least one ' + (rowNoun || 'row'));
    return false;
  }
  return true;
}

/* first row whose stored value for `fieldName` is empty */
function reqFirstEmptyRow(tbodyId, fieldName) {
  const rows = qsa('#' + tbodyId + ' tr');
  for (let i = 0; i < rows.length; i++) {
    const el = qs('[data-f="' + fieldName + '"]', rows[i]);
    if (!el) continue;
    const v = el.dataset.cbInput ? cboxGet(el.dataset.cbInput) : el.value;
    if (!String(v || '').trim()) return i;
  }
  return 0;
}
/* clear a field's error state as soon as the user touches it */
document.addEventListener('input', function (e) {
  const el = e.target.closest ? e.target.closest('.inp') : null;
  if (!el) return;
  el.classList.remove('inp-bad');
  const box = el.closest('.cbox') || el.closest('.mcbox');
  if (box) box.classList.remove('cbox-bad');
  const fld = el.closest('.field'); if (fld) fld.classList.remove('field-bad');
  const td = el.closest('td'); if (td) td.classList.remove('cell-bad');
}, true);

/* ---------- Toast ---------- */
function toast(msg, type) {
  const wrap = $('toastWrap');
  const t = document.createElement('div');
  t.className = 'toast' + (type ? ' ' + type : '');
  t.innerHTML = '<span class="ti">' + ic(type === 'red' ? 'x' : 'check', 16) + '</span><span>' + esc(msg) + '</span>';
  wrap.appendChild(t);
  setTimeout(() => { t.classList.add('out'); setTimeout(() => t.remove(), 320); }, 2800);
}
/* ---------- Re-confirm dialog (replaces window.confirm everywhere) ---------- */
let DLG = null;
function closeDialog() {
  const ov = $('appDialog'); if (ov) ov.classList.remove('show');
  if (DLG && typeof DLG.onCancel === 'function') { try { DLG.onCancel(); } catch(e){} }
  DLG = null;
}
/* opts: title, message(html), confirmText, cancelText, danger, bodyHtml, after(), onConfirm() */
function openDialog(opts) {
  opts = opts || {};
  const ov = $('appDialog'), box = $('appDialogBox');
  if (!ov || !box) { if (opts.onConfirm) opts.onConfirm(); return; }
  DLG = opts;
  // v5: ensure dialog overlay is above the auth-login screen (z-index 999)
  ov.style.zIndex = '9999';
  box.className = 'modal ' + (opts.itemSize ? 'modal-item' : opts.wide ? 'modal-xl' : 'modal-sm');
  box.innerHTML =
    '<div class="modal-head"><h3>' + esc(opts.title || 'Please confirm') + '</h3>' +
      '<button class="btn-icon" title="Close" onclick="closeDialog()">' + ic('x', 15) + '</button></div>' +
    '<div class="modal-body">' +
      (opts.message ? '<div class="dlg-msg">' + opts.message + '</div>' : '') +
      (opts.bodyHtml || '') +
      (opts.note ? '<div class="dlg-note">' + opts.note + '</div>' : '') +
    '</div>' +
    '<div class="modal-foot">' +
      '<button class="btn btn-ghost" onclick="closeDialog()">' + esc(opts.cancelText || 'Cancel') + '</button>' +
      '<button class="btn ' + (opts.danger ? 'btn-critical' : 'btn-primary') + '" id="dlg-ok">' + esc(opts.confirmText || 'Confirm') + '</button>' +
    '</div>';
  ov.classList.add('show');
  const ok = $('dlg-ok');
  if (ok) ok.onclick = function () {
    const fn = DLG && DLG.onConfirm;
    let keep = false;
    if (fn) keep = fn() === false;      /* return false to keep the dialog open */
    if (!keep) closeDialog();
  };
  if (typeof opts.after === 'function') setTimeout(opts.after, 0);
  else setTimeout(function () { if (ok) ok.focus(); }, 0);
}
/* standard delete re-confirmation */
function confirmDelete(what, onYes, note) {
  openDialog({
    title: 'Delete ' + what.kind,
    message: 'Are you sure you want to delete <span class="dlg-strong">' + esc(what.name) + '</span>? This action cannot be undone.',
    note: note || '',
    bodyHtml: what.bodyHtml || '',
    confirmText: what.confirmText || 'Delete',
    danger: true,
    onConfirm: onYes
  });
}
document.addEventListener('keydown', function (e) {
  if (e.key === 'Escape' && DLG) { e.stopPropagation(); closeDialog(); }
}, true);
const _appDlgOv = null;
setTimeout(function () {
  const ov = document.getElementById('appDialog');
  if (ov) ov.addEventListener('mousedown', function (e) { if (e.target === ov) closeDialog(); });
}, 0);

function toastUndo(msg, undoFn) {
  const wrap = $('toastWrap');
  const t = document.createElement('div');
  t.className = 'toast';
  const key = 'u' + Date.now().toString(36);
  window['__undo_' + key] = function () { undoFn(); t.classList.add('out'); setTimeout(() => t.remove(), 300); };
  t.innerHTML = '<span class="ti">' + ic('trash', 16) + '</span><span>' + esc(msg) + '</span>' +
                '<button class="tundo" onclick="window.__undo_' + key + '()">Undo</button>';
  wrap.appendChild(t);
  setTimeout(() => { t.classList.add('out'); setTimeout(() => { t.remove(); delete window['__undo_' + key]; }, 320); }, 6000);
}

/* =====================================================================
   SEARCHABLE COMBOBOX — used for EVERY dropdown in the app
   ===================================================================== */
const CBOX = {};
let cbCounter = 0;
function rid(prefix) { return prefix + (++cbCounter) + '_' + Math.random().toString(36).slice(2, 6); }

function findMasterId(val, keyHint) {
  if (val == null || typeof val !== 'string') return '';
  const vRaw = String(val).trim();
  if (!vRaw) return '';
  const v = vRaw.replace(/^\[[^\]]*\]\s*/, '').trim();
  const vl = v.toLowerCase();

  if (typeof db === 'undefined' || !db || !db.masters) return '';

  if (keyHint === 'parties' || (!keyHint && db.masters.parties)) {
    const p = (db.masters.parties || []).find(function (x) {
      return String(x.shortName || '').trim().toLowerCase() === vl ||
             String(x.legalName || '').trim().toLowerCase() === vl ||
             String(x.code || '').trim().toLowerCase() === vl ||
             String(x.id || '').trim().toLowerCase() === vl;
    });
    if (p && (p.code || p.id)) return p.code || p.id;
  }

  if (keyHint === 'items' || (!keyHint && db.masters.items)) {
    const it = (db.masters.items || []).find(function (x) {
      return String(x.name || '').trim().toLowerCase() === vl ||
             String(x.code || '').trim().toLowerCase() === vl;
    });
    if (it && (it.code || it.id)) return it.code || it.id;
  }

  if (keyHint === 'styles' || (!keyHint && db.masters.styles)) {
    const st = (db.masters.styles || []).find(function (x) {
      return String(x.internal || '').trim().toLowerCase() === vl ||
             String(x.portal || '').trim().toLowerCase() === vl ||
             String(x.code || x.id || '').trim().toLowerCase() === vl;
    });
    if (st && (st.code || st.id || st.internal_id)) return st.code || st.id || st.internal_id;
  }

  if (keyHint && db.masters[keyHint] && Array.isArray(db.masters[keyHint]) && typeof masterIdFor === 'function') {
    return masterIdFor(keyHint, v);
  }

  if (typeof masterIdFor === 'function') {
    const listKeys = [
      'warehouses', 'categories', 'classifications', 'uoms', 'sizes',
      'processTypes', 'paymentTermsList', 'transportModes', 'washTypes',
      'gstRates', 'gstTypes', 'suppliers', 'customers', 'freightChargesList',
      'returnTypes', 'raisedForList', 'businessTypes', 'qualities', 'qcResults',
      'partyStatuses', 'countries', 'states'
    ];
    for (let i = 0; i < listKeys.length; i++) {
      const k = listKeys[i];
      const arr = db.masters[k];
      if (Array.isArray(arr) && arr.some(function (x) { return String(x).trim().toLowerCase() === vl; })) {
        return masterIdFor(k, v);
      }
    }
  }

  return '';
}

function normalizeOpt(o, keyHint) {
  let opt = (typeof o === 'string') ? { v: o, l: o } : Object.assign({}, o);
  if (!opt.v) return opt;
  if (!opt.mid) {
    opt.mid = findMasterId(opt.v, keyHint);
  }
  if (opt.mid) {
    const prefix = '[' + opt.mid + '] ';
    if (!String(opt.l).startsWith('[') && !String(opt.l).startsWith(prefix)) {
      opt.l = prefix + opt.l;
    }
  }
  return opt;
}

function cbox(id, cfg) {
  cfg = cfg || {};
  const keyHint = cfg.addMaster || cfg.masterKey || null;
  const c = {
    id: id,
    opts: (cfg.opts || []).map(function(o){ return normalizeOpt(o, keyHint); }).filter(function(o){return masterValueAllowed(o.v);}),
    val: cfg.value != null ? cfg.value : '',
    placeholder: cfg.placeholder || 'Select…',
    /* Every combobox is strictly list-only: typing filters the options but a
       value that is not on the list can never be committed, and no combobox
       may create a new master value. New values are added in Masters /
       Item Master / Party onboarding, never inline on a document. */
    free: false,
    onSet: cfg.onSet || null,
    addMaster: cfg.addMaster || null,
    addText: cfg.addText || null,
    emptyMsg: cfg.emptyMsg || null,
    compact: !!cfg.compact,
    display: cfg.display != null ? cfg.display : null
  };
  /* A value already stored on a saved record must stay selectable even if it
     is no longer in the master list — otherwise strict mode would silently
     wipe historical data when the record is reopened. */
  if (c.val !== '' && c.val != null && !c.opts.some(function (o) { return o.v === c.val; })) {
    const missingOpt = normalizeOpt({ v: c.val, l: (c.display != null ? c.display : String(c.val)) }, keyHint);
    c.opts = c.opts.concat([missingOpt]);
  }
  const hit = c.opts.find(function (o) { return o.v === c.val; });
  if (hit && c.display == null) {
    c.display = hit.l;
  }
  CBOX[id] = c;
  return '<div class="cbox' + (c.compact ? ' compact' : '') + '" data-cb="' + id + '">' +
    '<input type="text" class="inp cbox-input" data-cb-input="' + id + '"' + (cfg.f ? ' data-f="' + cfg.f + '"' : '') + ' placeholder="' + esc(c.placeholder) + '" value="' + esc(c.display != null ? c.display : c.val) + '" autocomplete="off" spellcheck="false">' +
    '<span class="cbox-caret">' + ic('select', 16) + '</span><div class="cbox-list"></div></div>';
}

function cboxSet(id, v) {
  const c = CBOX[id]; if (!c) return;
  c.val = v;
  const hit = c.opts.find(function (o) { return o.v === v; });
  c.display = hit ? hit.l : v;
  const inp = qs('[data-cb-input="' + id + '"]');
  if (inp) inp.value = hit ? hit.l : v;
  renderCboxList(id);
}
function cboxGet(id) { const c = CBOX[id]; return c ? c.val : ''; }
function cboxGetId(id) {
  const c = CBOX[id]; if (!c) return '';
  const hit = c.opts.find(function (o) { return o.v === c.val; });
  return hit ? (hit.mid || findMasterId(c.val)) : findMasterId(c.val);
}

function toggleCbox(id) {
  const c = CBOX[id]; if (!c) return;
  const box = qs('[data-cb="' + id + '"]');
  const wasOpen = box && box.classList.contains('open');
  closeAllCbox();
  if (!wasOpen) {
    if (box) box.classList.add('open');
    c.typed = false;                    // fresh open → show every option, not just the current value
    renderCboxList(id);
    const inp = qs('[data-cb-input="' + id + '"]');
    if (inp) { inp.focus(); try { inp.select(); } catch (e) {} }
  }
}
/* Anchor a floating panel to its trigger. Because the list is position:fixed it
   escapes .table-wrap / modal overflow clipping instead of being cut off. */
function placeFloatList(box, list) {
  if (!box || !list) return;
  const r = box.getBoundingClientRect();
  const vh = window.innerHeight, vw = window.innerWidth, gap = 4, margin = 8;
  list.style.width = 'auto';
  list.style.minWidth = Math.max(180, r.width) + 'px';
  list.style.maxHeight = '250px';
  const h = Math.min(list.scrollHeight + 2, 250);
  const below = vh - r.bottom - gap, above = r.top - gap;
  let top;
  if (below >= h || below >= above) { top = r.bottom + gap; list.style.maxHeight = Math.min(250, Math.max(120, below - margin)) + 'px'; }
  else { top = Math.max(margin, r.top - gap - Math.min(h, above - margin)); list.style.maxHeight = Math.min(250, Math.max(120, above - margin)) + 'px'; }
  const w = Math.max(180, r.width);
  let left = r.left;
  if (left + w > vw - margin) left = Math.max(margin, vw - margin - w);
  list.style.top = Math.round(top) + 'px';
  list.style.left = Math.round(left) + 'px';
}
/* The calendar is a fixed-size panel: place it whole, flipping above the field
   when there isn't room below. Never shrink it into an internal scroller. */
function placeCalendar(input, el) {
  if (!input || !el) return;
  const r = input.getBoundingClientRect();
  const vw = window.innerWidth, vh = window.innerHeight, gap = 6, margin = 8;
  const w = el.offsetWidth || 284, hh = el.offsetHeight || 330;
  let top;
  if (r.bottom + gap + hh <= vh - margin) top = r.bottom + gap;          // below
  else if (r.top - gap - hh >= margin)    top = r.top - gap - hh;        // above
  else top = Math.max(margin, vh - margin - hh);                          // pin inside
  let left = r.left;
  if (left + w > vw - margin) left = vw - margin - w;
  if (left < margin) left = margin;
  el.style.top = Math.round(top) + 'px';
  el.style.left = Math.round(left) + 'px';
}
function repositionOpenLists() {
  qsa('.cbox.open').forEach(b => placeFloatList(b, qs('.cbox-list', b)));
  qsa('.mcbox.open').forEach(b => placeFloatList(b, qs('.mcbox-list', b)));
}
/* keep panels glued to their field while scrolling / resizing */
window.addEventListener('scroll', repositionOpenLists, true);
window.addEventListener('resize', repositionOpenLists);

function closeCbox(id) { const box = qs('[data-cb="' + id + '"]'); if (box) box.classList.remove('open'); }
function closeAllCbox() { qsa('.cbox.open').forEach(b => b.classList.remove('open')); }

function renderCboxList(id) {
  const c = CBOX[id]; if (!c) return;
  const box = qs('[data-cb="' + id + '"]'); if (!box) return;
  const list = qs('.cbox-list', box); if (!list) return;

  if (id === 'jw-style' || (id && id.indexOf('style') > -1 && id !== 'dlg-st-buyer' && !id.startsWith('dlg-st-') && !id.startsWith('m-style-'))) {
    if (typeof styleOpts === 'function') {
      c.opts = styleOpts().map(function(o){ return normalizeOpt(o, 'styles'); }).filter(function(o){ return masterValueAllowed(o.v); });
    }
  }

  const inp = qs('.cbox-input', box);
  const txt = (inp ? inp.value : c.val) || '';
  const q = c.typed ? txt.toLowerCase().trim() : '';
  c.visible = c.opts.filter(o => !q || o.l.toLowerCase().includes(q) || (o.v && String(o.v).toLowerCase().includes(q)) || (o.mid && String(o.mid).toLowerCase().includes(q)));
  if (!c.visible.length && c.addMaster === 'items' && typeof itemOpts === 'function') {
    const allItemOpts = itemOpts().map(function(o){ return normalizeOpt(o, 'items'); }).filter(function(o){ return masterValueAllowed(o.v); });
    const globalMatches = q
      ? allItemOpts.filter(o => o.l.toLowerCase().includes(q) || (o.v && String(o.v).toLowerCase().includes(q)) || (o.mid && String(o.mid).toLowerCase().includes(q)))
      : (c.opts.length === 0 ? allItemOpts : []);
    if (globalMatches.length) {
      c.visible = globalMatches;
    }
  }
  c.active = null;
  let h = '';
  if (c.opts.length > 7) h += '<div class="cbox-search">' + ic('search', 13) + (q ? esc(txt) : 'Type to filter ' + c.opts.length + ' options') + '</div>';
  if (!c.visible.length) h += '<div class="cbox-empty">' +
    (c.opts.length ? 'No matching option — only listed values are allowed' : (c.emptyMsg || (c.addMaster ? 'No options available — add them in Masters first' : 'No records available'))) + '</div>';
  c.visible.forEach(o => {
    h += '<div class="cbox-opt" data-val="' + esc(o.v) + '" data-label="' + esc(o.l) + '">' + esc(o.l) +
         (o.v === c.val ? '<span class="tick">✓</span>' : '') + '</div>';
  });
  /* no inline "+ Add" — only values already on the list can be picked */
  list.innerHTML = h;
  if (box.classList.contains('open')) placeFloatList(box, list);
}

function pickCbox(id, v, label) {
  const c = CBOX[id]; if (!c) return;
  c.val = v; c.typed = false;
  /* remember the label actually shown so a later blur restores it, not the raw value */
  c.display = (label != null) ? label : ((c.opts.find(function (o) { return o.v === v; }) || {}).l || null);
  const _b = qs('[data-cb="' + id + '"]');
  if (_b) { _b.classList.remove('cbox-bad');
    const _f = _b.closest('.field'); if (_f) _f.classList.remove('field-bad');
    const _t = _b.closest('td'); if (_t) _t.classList.remove('cell-bad'); }
  const inp = qs('[data-cb-input="' + id + '"]');
  if (inp) inp.value = c.display != null ? c.display : (label != null ? label : v);
  closeCbox(id);
  if (c.onSet) c.onSet(v);
}
/* retained for compatibility — comboboxes are list-only, nothing is added inline */
function addCboxValue(id) {
  toast('New values must be added in Masters first \u2014 only listed options can be selected', 'red');
  return;
  /* eslint-disable no-unreachable */
  const c = CBOX[id]; if (!c || !c.addMaster) return;
  const inp = qs('[data-cb-input="' + id + '"]');
  const v = (inp ? inp.value : '').trim();
  if (!v) return;
  const dupErr = masterDupError(c.addMaster, v);
  if (dupErr) { reqBad(inp, dupErr); return; }
  const vErr = masterValueError(c.addMaster, v);
  if (vErr) { reqBad(inp, vErr); return; }
  addMasterVal(c.addMaster, v, true);
  pickCbox(id, v);
  toast('Added “' + v + '” to ' + (c.addText || c.addMaster), 'green');
}
function moveCbox(id, dir) {
  const c = CBOX[id]; if (!c || !c.visible || !c.visible.length) return;
  const box = qs('[data-cb="' + id + '"]'); if (!box) return;
  let idx = c.visible.findIndex(o => o.v === c.active);
  idx = (idx + dir + c.visible.length) % c.visible.length;
  c.active = c.visible[idx].v;
  qsa('.cbox-opt', box).forEach(el => el.classList.toggle('active', el.dataset.val === c.active));
  const act = qs('.cbox-opt.active', box);
  if (act && act.scrollIntoView) act.scrollIntoView({ block: 'nearest' });
}

/* =====================================================================
   MULTI-SELECT COMBOBOX — used for size selection per style row
   ===================================================================== */
const MCBOX = {};
const rowSz = {};    // per-style-row size values: { szId: { sizes: {S:'10',...} } }
const rowIss = {};   // per-issue-row size consumption values: { szId: { sizes: {S:'1.2',...}, sel: [...] } }
const PODDATA = {}; // per-issue-row POD uploads: { podId: { pod: dataURL, podName } }

function mcbox(id, cfg) {
  cfg = cfg || {};
  const opts = (cfg.opts || []).map(normalizeOpt).filter(function(o){return masterValueAllowed(o.v);});
  const sel = (cfg.selected || []).slice();
  MCBOX[id] = { id: id, opts: opts, sel: sel, onSet: cfg.onSet || null, placeholder: cfg.placeholder || 'Select…',
                locked: (cfg.locked || []).slice(), lockMsg: cfg.lockMsg || 'This size is already saved on the entry and cannot be removed',
                disabled: !!cfg.disabled, typed: false, q: '' };
  return '<div class="mcbox' + (cfg.disabled ? ' disabled' : '') + '" data-mcb="' + id + '">' +
    '<input type="text" class="inp mcbox-input" data-mcb-input="' + id + '" value="' + esc(mcboxLabel(id)) + '" placeholder="' + esc(cfg.placeholder || 'Select…') + '" autocomplete="off" spellcheck="false"' + (cfg.disabled ? ' disabled' : '') + ' oninput="mcboxFilter(\'' + id + '\',this.value)">' +
    '<span class="cbox-caret">' + ic('select', 16) + '</span><div class="mcbox-list"></div></div>';
}
function mcboxGet(id) { const c = MCBOX[id]; return c ? c.sel.slice() : []; }
/* type-to-search inside a multi-select */
function mcboxFilter(id, v) {
  const c = MCBOX[id]; if (!c) return;
  c.typed = true; c.q = String(v || '');
  const box = qs('[data-mcb="' + id + '"]');
  if (box && !box.classList.contains('open')) box.classList.add('open');
  renderMcboxList(id);
}
function mcboxLabel(id) { const c = MCBOX[id]; if (!c) return ''; return c.opts.filter(o => c.sel.indexOf(o.v) > -1).map(o => o.l).join(', '); }
function mcboxLocked(id, v) {
  const c = MCBOX[id];
  return !!(c && c.locked && c.locked.indexOf(v) > -1);
}
function renderMcboxList(id) {
  const c = MCBOX[id]; if (!c) return;
  const box = qs('[data-mcb="' + id + '"]'); if (!box) return;
  const list = qs('.mcbox-list', box); if (!list) return;

  // Dynamically refresh styles options from Style Master database records
  if (id === 'po-styles' || id === 'smp-styles' || (id && id.indexOf('style') > -1)) {
    if (typeof styleOpts === 'function') {
      const currentBuyer = (typeof cboxGet === 'function') ? (cboxGet('po-buyer') || cboxGet('smp-buyer') || '') : '';
      const dynamicOpts = styleOpts(currentBuyer);
      c.opts = dynamicOpts.map(normalizeOpt).filter(function(o){ return masterValueAllowed(o.v); });
    }
  }

  const q = (c.typed && c.q) ? String(c.q).toLowerCase().trim() : '';
  const shown = q ? c.opts.filter(function (o) {
    return String(o.l).toLowerCase().indexOf(q) > -1 || String(o.v).toLowerCase().indexOf(q) > -1;
  }) : c.opts;
  const currentBuyer = (typeof cboxGet === 'function') ? (cboxGet('po-buyer') || cboxGet('smp-buyer') || '') : '';
  const emptyHint = q ? 'No matches for “' + esc(c.q) + '”' : (currentBuyer ? 'No styles found for “' + esc(currentBuyer) + '”' : 'No styles available in Style Master');
  list.innerHTML = '<div class="mcbox-hint">selected: ' + esc(mcboxLabel(id) || 'none') + ' — click to toggle</div>' +
    (shown.length ? shown.map(function (o) {
      const lock = mcboxLocked(id, o.v);
      return '<div class="mcbox-opt' + (lock ? ' mcbox-lock' : '') + '" data-val="' + esc(o.v) + '"' +
        (lock ? ' title="' + esc(c.lockMsg) + '"' : '') + '>' + esc(o.l) +
        (c.sel.indexOf(o.v) > -1 ? '<span class="tick">' + (lock ? ic('lock', 12) : '✓') + '</span>' : '') + '</div>';
    }).join('') : '<div class="cbox-empty">' + emptyHint + '</div>');
  if (box.classList.contains('open')) placeFloatList(box, list);
}
function updateMcboxInput(id) {
  const c = MCBOX[id]; if (!c) return;
  if (c.typed) return;                       /* never clobber the search text */
  const inp = qs('[data-mcb-input="' + id + '"]');
  if (inp) inp.value = mcboxLabel(id);
}
function closeAllMcbox() {
  qsa('.mcbox.open').forEach(function (b) {
    b.classList.remove('open');
    const id = b.dataset.mcb, c = MCBOX[id];
    if (c) { c.typed = false; c.q = ''; }
    const inp = qs('.mcbox-input', b);
    if (inp) inp.value = mcboxLabel(id);
  });
}

/* global delegated events for combos + multiselect */
document.addEventListener('click', function (e) {
  const mbox = e.target.closest ? e.target.closest('.mcbox') : null;
  if (mbox) {
    const id = mbox.dataset.mcb; const c = MCBOX[id];
    const opt = e.target.closest('.mcbox-opt');
    if (opt && c) {
      const v = opt.dataset.val;
      const i = c.sel.indexOf(v);
      if (i > -1 && mcboxLocked(id, v)) { toast(c.lockMsg, 'red'); return; }
      if (i > -1) c.sel.splice(i, 1); else c.sel.push(v);
      c.sel = c.opts.map(o => o.v).filter(x => c.sel.indexOf(x) > -1);   // keep master order
      c.typed = false; c.q = '';
      updateMcboxInput(id); renderMcboxList(id);
      if (c.onSet) c.onSet(c.sel.slice());
      return;
    }
    const onInput = !!(e.target.closest && e.target.closest('.mcbox-input'));
    const wasOpen = mbox.classList.contains('open');
    if (wasOpen && onInput) return;                    /* keep open so you can type */
    closeAllMcbox();
    if (!wasOpen) { mbox.classList.add('open'); renderMcboxList(id); }
    return;
  }
  const box = e.target.closest ? e.target.closest('.cbox') : null;
  if (box) {
    if (e.target.closest('.cbox-opt')) {
      const opt = e.target.closest('.cbox-opt');
      pickCbox(box.dataset.cb, opt.dataset.val, opt.dataset.label);
      return;
    }
    if (e.target.closest('.cbox-add')) { addCboxValue(box.dataset.cb); return; }
    toggleCbox(box.dataset.cb); return;
  }
  closeAllCbox(); closeAllMcbox();
});
document.addEventListener('input', function (e) {
  if (e.target && e.target.matches && e.target.matches('.cbox-input')) {
    const id = e.target.dataset.cbInput;
    const c = CBOX[id];
    if (c) c.typed = true;                     // user is filtering now — the typed
                                               // text is never stored as a value
    if (c && c.onSet) {                        // auto-fire onSet when typed text matches an option
      const val = String(e.target.value || '').trim().toLowerCase();
      const exact = c.opts.find(o => String(o.l || '').toLowerCase() === val || String(o.v || '').toLowerCase() === val || (o.mid && (String(o.mid).toLowerCase() === val || ('[' + String(o.mid).toLowerCase() + ']') === val)));
      if (exact) { c.val = exact.v; c.display = exact.l; c.onSet(exact.v); }
    }
    const box = qs('[data-cb="' + id + '"]');
    if (box && !box.classList.contains('open')) box.classList.add('open');
    renderCboxList(id);
  }
});
document.addEventListener('blur', function (e) {
  if (!e.target || !e.target.matches || !e.target.matches('.cbox-input')) return;
  const id = e.target.dataset.cbInput;
  const c = CBOX[id]; if (!c) return;
  setTimeout(function () {
    const box = qs('[data-cb="' + id + '"]');
    const inp = qs('[data-cb-input="' + id + '"]');
    if (!inp) return;
    /* anything that is an exact option snaps to it and updates onSet */
    const val = String(inp.value || '').trim().toLowerCase();
    const exact = c.opts.find(o => String(o.l || '').toLowerCase() === val || String(o.v || '').toLowerCase() === val || (o.mid && (String(o.mid).toLowerCase() === val || ('[' + String(o.mid).toLowerCase() + ']') === val)));
    if (exact) {
      const changed = c.val !== exact.v;
      c.val = exact.v;
      c.display = exact.l;
      inp.value = exact.l;
      if (changed && c.onSet) c.onSet(exact.v);
    } else {
      const wasTyped = String(inp.value || '').trim();
      inp.value = (c.display != null && c.val) ? c.display : c.val;
      if (wasTyped && wasTyped !== String(inp.value || '').trim()) {
        toast('\u201c' + wasTyped + '\u201d is not in the list \u2014 pick an available option', 'red');
      }
    }
    if (box) box.classList.remove('open');
  }, 130);
}, true);
document.addEventListener('keydown', function (e) {
  if (!e.target || !e.target.matches || !e.target.matches('.cbox-input')) return;
  const id = e.target.dataset.cbInput;
  if (e.key === 'ArrowDown') { e.preventDefault(); moveCbox(id, 1); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); moveCbox(id, -1); }
  else if (e.key === 'Enter') {
    e.preventDefault();
    const c = CBOX[id];
    if (c && c.active) pickCbox(id, c.active);
    else if (c && c.visible && c.visible.length === 1) pickCbox(id, c.visible[0].v, c.visible[0].l);
    else toggleCbox(id);
  }
  else if (e.key === 'Escape') { closeCbox(id); }
});

