function isHashedPin(v){ return /^sha256:[0-9a-f]{64}$/i.test(String(v||'')); }
function sha256hex(str){
  function rotr(n,x){return (x>>>n)|(x<<(32-n));}
  var k=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  var bytes=[];
  for(var i=0;i<str.length;i++){
    var c=str.charCodeAt(i);
    if(c<0x80)bytes.push(c);
    else if(c<0x800)bytes.push(0xc0|c>>6,0x80|c&63);
    else bytes.push(0xe0|c>>12,0x80|c>>6&63,0x80|c&63);
  }
  var bit=bytes.length*8;
  bytes.push(0x80);
  while((bytes.length%64)!==56)bytes.push(0);
  for(var j=7;j>=0;j--)bytes.push((bit/Math.pow(2,j*8))&255);
  var h0=0x6a09e667,h1=0xbb67ae85,h2=0x3c6ef372,h3=0xa54ff53a,h4=0x510e527f,h5=0x9b05688c,h6=0x1f83d9ab,h7=0x5be0cd19;
  for(var off=0;off<bytes.length;off+=64){
    var w=new Array(64);
    for(i=0;i<16;i++)w[i]=(bytes[off+i*4]<<24)|(bytes[off+i*4+1]<<16)|(bytes[off+i*4+2]<<8)|bytes[off+i*4+3];
    for(i=16;i<64;i++){
      var s0=rotr(7,w[i-15])^rotr(18,w[i-15])^(w[i-15]>>>3);
      var s1=rotr(17,w[i-2])^rotr(19,w[i-2])^(w[i-2]>>>10);
      w[i]=(w[i-16]+s0+w[i-7]+s1)|0;
    }
    var a=h0,b=h1,c=h2,d=h3,e=h4,f=h5,g=h6,h=h7;
    for(i=0;i<64;i++){
      var S1=rotr(6,e)^rotr(11,e)^rotr(25,e);
      var ch=(e&f)^((~e)&g);
      var t1=(h+S1+ch+k[i]+w[i])|0;
      var S0=rotr(2,a)^rotr(13,a)^rotr(22,a);
      var maj=(a&b)^(a&c)^(b&c);
      var t2=(S0+maj)|0;
      h=g;g=f;f=e;e=(d+t1)|0;d=c;c=b;b=a;a=(t1+t2)|0;
    }
    h0=(h0+a)|0;h1=(h1+b)|0;h2=(h2+c)|0;h3=(h3+d)|0;h4=(h4+e)|0;h5=(h5+f)|0;h6=(h6+g)|0;h7=(h7+h)|0;
  }
  function hx(n){return ('00000000'+(n>>>0).toString(16)).slice(-8);}
  return hx(h0)+hx(h1)+hx(h2)+hx(h3)+hx(h4)+hx(h5)+hx(h6)+hx(h7);
}
function hashPin(pin){ return 'sha256:'+sha256hex(String(pin||'')); }
function pinMatches(stored, entered){
  stored=String(stored||''); entered=String(entered||'');
  if(!entered) return false;
  if(isHashedPin(stored)) return stored.toLowerCase()===hashPin(entered).toLowerCase();
  return stored===entered;
}
function migrateUserPins(d){
  (d.users||[]).forEach(function(u){
    if(u && u.pin && !isHashedPin(u.pin)) u.pin=hashPin(u.pin);
  });
  return d;
}

