function migrate(old) {
  // v1 → v2 upgrades
  if (old.masters) {
    if (Array.isArray(old.masters.items) && old.masters.items.length && typeof old.masters.items[0] === 'string') {
      old.masters.items = old.masters.items.map(n => ({ name: n, category: 'Other', unit: '' }));
    }
    if (!Array.isArray(old.masters.colours)) old.masters.colours = ['White','Black','Navy Blue','Red','Maroon','Beige'];
    if (Array.isArray(old.masters.styles)) old.masters.styles = old.masters.styles.map(s => (typeof s === 'string') ? { internal: s, portal: '', desc: '' } : s);
  }
  if (old.workorder && old.workorder.length && !old.jobwork) {
    old.jobwork = old.workorder.map(w => ({
      id: w.id, no: 'JW-' + String(w.no || '').replace(/^WO-?/, ''), date: w.date || today(),
      vendor: w.contractor || '', fabricItem: w.fabric || 'Fabric', fabricQty: 0, fabricUnit: 'm', fabricColour: '',
      garment: w.style || '', colour: '', orderQty: sumBy(w.sizes, 'qty') || 0, rate: 0, charges: 0,
      issueDate: w.start || '', expectedDate: w.end || '', receiveDate: '', receivedQty: 0,
      status: ({ 'Planned':'Issued','In Production':'In Progress','Quality Check':'In Progress','Completed':'Completed','Cancelled':'Cancelled' })[w.status] || 'Issued',
      notes: w.desc || ''
    }));
    old.seq = old.seq || {}; old.seq.jobwork = old.seq.workorder || 0;
    delete old.workorder; delete old.seq.workorder;
  }
  return old;
}
function loadDB() {
  const d = migrateUserPins(normalizeDB(defaultDB()));
  try { seedParentMap(d); ensureMasterIds(d); } catch(e){}
  return d;
}
function currentAuditUser(){try{const u=typeof authUser==='function'?authUser():null;if(u)return u.name||u.username;return localStorage.getItem('stitchflow_audit_user')||'StitchFlow User';}catch(e){return 'StitchFlow User';}}
function setAuditUser(){openDialog({title:'Set audit user',message:'Changes saved from this browser will be recorded under this name.',bodyHtml:'<div class="dlg-field"><label>User name *</label><input class="inp" id="audit-user-name" value="'+esc(currentAuditUser())+'"></div>',confirmText:'Save user',onConfirm:function(){const v=(($('audit-user-name')||{}).value||'').trim();if(!v)return reqBad('audit-user-name','User name is required');try{localStorage.setItem('stitchflow_audit_user',v);}catch(e){}toast('Audit user set to '+v,'green');if(cur==='audit')render();}});}
let AUDIT_PREV = null;
function auditSafe(v) {
  if (typeof v === 'string' && /^data:/i.test(v)) return '[attachment ' + Math.round(v.length / 1024) + ' KB]';
  if (Array.isArray(v)) return v.map(auditSafe);
  if (v && typeof v === 'object') {
    const o = {}; Object.keys(v).forEach(function(k){ if(k !== 'createdAt') o[k]=auditSafe(v[k]); }); return o;
  }
  return v;
}
function auditSnapshot(d) {
  const snap={modules:{},masters:{}};
  MODULE_KEYS.forEach(function(k){snap.modules[k]=auditSafe((d[k]||[]));});
  Object.keys((d&&d.masters)||{}).forEach(function(k){if(k!=='parentMap'&&k!=='warehouseAddr'&&k!=='masterIds'&&k!=='masterIdSeq'&&k!=='masterStatus'&&k!=='loginSettings'&&k!=='menuSettings')snap.masters[k]=auditSafe(d.masters[k]);});
  return snap;
}
function auditRecordKey(r,i){return String((r&&(r.id||r.no||r.code||r.internal||r.name))||('#'+i));}
function auditShort(v){
  if(v==null||v==='')return 'blank';
  if(typeof v==='object'){const s=JSON.stringify(v);return s.length>80?s.slice(0,77)+'…':s;}
  const s=String(v);return s.length>80?s.slice(0,77)+'…':s;
}
function auditHighlights(r){
  r=r||{};const labels={date:'Date',supplier:'Supplier',vendor:'Vendor',customer:'Customer',processType:'Process',processor:'Processor',status:'Status',warehouse:'Warehouse',jwRef:'Job Work Ref',outwardRef:'Outward Ref',name:'Name'};
  const out=[];Object.keys(labels).forEach(function(k){if(r[k]!=null&&r[k]!==''&&out.length<5)out.push(labels[k]+': '+auditShort(r[k]));});return out;
}
function auditDiff(a,b,path,out){
  out=out||[];path=path||'';if(out.length>=20)return out;
  if(JSON.stringify(a)===JSON.stringify(b))return out;
  const ao=a&&typeof a==='object',bo=b&&typeof b==='object';
  if(ao&&bo&&!Array.isArray(a)&&!Array.isArray(b)){
    const keys=Array.from(new Set(Object.keys(a).concat(Object.keys(b))));
    keys.forEach(function(k){if(out.length<20)auditDiff(a[k],b[k],path?(path+'.'+k):k,out);});return out;
  }
  if(Array.isArray(a)&&Array.isArray(b)){
    const n=Math.max(a.length,b.length);for(let i=0;i<n&&out.length<20;i++)auditDiff(a[i],b[i],path+'['+i+']',out);return out;
  }
  out.push((path||'value')+': '+auditShort(a)+' → '+auditShort(b));return out;
}
function auditPush(area,action,record,changes){
  if(!Array.isArray(db.auditTrail))db.auditTrail=[];
  db.auditTrail.push({id:uid(),at:new Date().toISOString(),user:currentAuditUser(),area:area,action:action,record:record||'—',changes:(changes||[]).slice(0,20)});
  if(db.auditTrail.length>2000)db.auditTrail=db.auditTrail.slice(-2000);
}
function captureAuditChanges(){
  if(!AUDIT_PREV||!db)return;
  const now=auditSnapshot(db);
  MODULE_KEYS.forEach(function(k){
    const oldArr=AUDIT_PREV.modules[k]||[],newArr=now.modules[k]||[];
    const om={},nm={};oldArr.forEach(function(r,i){om[auditRecordKey(r,i)]=r;});newArr.forEach(function(r,i){nm[auditRecordKey(r,i)]=r;});
    const area=(MODULES[k]&&MODULES[k].label)||k;
    Object.keys(nm).forEach(function(key){if(!om[key]){const h=auditHighlights(nm[key]);auditPush(area,'Created',nm[key].no||nm[key].code||key,h.length?h:['New record created']);}else{const d=auditDiff(om[key],nm[key]);if(d.length)auditPush(area,'Updated',nm[key].no||nm[key].code||key,d);}});
    Object.keys(om).forEach(function(key){if(!nm[key]){const h=auditHighlights(om[key]);auditPush(area,'Deleted',om[key].no||om[key].code||key,h.length?h:['Record deleted']);}});
  });
  Object.keys(now.masters).forEach(function(k){
    const a=AUDIT_PREV.masters[k]||[],b=now.masters[k]||[];if(JSON.stringify(a)===JSON.stringify(b))return;
    const area=k==='items'?'Item Master':k==='parties'?'Party onboarding':k==='styles'?'Style Master':('Master — '+k);
    if(Array.isArray(a)&&Array.isArray(b)){
      const objectList=(a.concat(b)).some(function(x){return x&&typeof x==='object';});
      if(objectList){const am={},bm={};a.forEach(function(x,i){am[auditRecordKey(x,i)]=x;});b.forEach(function(x,i){bm[auditRecordKey(x,i)]=x;});Object.keys(bm).forEach(function(key){if(!am[key])auditPush(area,'Added',key,['Master record added']);else{const d=auditDiff(am[key],bm[key]);if(d.length)auditPush(area,'Updated',key,d);}});Object.keys(am).forEach(function(key){if(!bm[key])auditPush(area,'Removed',key,['Master record removed']);});}
      else{b.forEach(function(v){if(!a.some(function(x){return String(x).toLowerCase()===String(v).toLowerCase();}))auditPush(area,'Added',String(v),['Master value added']);});a.forEach(function(v){if(!b.some(function(x){return String(x).toLowerCase()===String(v).toLowerCase();}))auditPush(area,'Removed',String(v),['Master value removed']);});}
    }
  });
  AUDIT_PREV=now;
}
function sfServerBase(){
  try{
    if(typeof location==='undefined'||!/^https?:/i.test(location.protocol)) return '';
    if(window.__API_BASE__) return window.__API_BASE__;
    var path = String(location.pathname||'/');
    var pIdx = path.indexOf('/pages/');
    if (pIdx > -1) return path.slice(0, pIdx + 1);
    var aIdx = path.indexOf('/app/');
    if (aIdx > -1) return path.slice(0, aIdx + 1);
    var base = path.replace(/\/[^\/]*$/,'/');
    if(base.slice(-1)!=='/') base+='/';
    return base;
  }catch(e){return '';}
}
