    supplier: $('pr-supplier').value.trim(), debitNote: (id ? ((db.purchasereturn.find(function (x) { return x.id === id; }) || {}).debitNote || '') : ''),
    vehicle: $('pr-vehicle').value.trim(), warehouse: cboxGet('pr-warehouse'),
