function clearAll() {
  openDialog({
    title: 'Clear all data',
    message: 'This will permanently delete <span class="dlg-strong">every record AND every master</span> in this workspace and reset it to a blank state.',
    bodyHtml:
      '<div class="dlg-note" style="background:#fff5ea;border-left:4px solid #ffb800;color:#5e4200">' +
        '<b>This will clear:</b><br>' +
        '&bull; All Purchase Orders, Inward, Job Work, Process Outward, Process Inward, Sample, Sale, Costing, Purchase Return, Job Work Return entries<br>' +
        '&bull; All Style Master, Item Master, Party onboarding records<br>' +
        '&bull; All custom masters (sizes, colours, classifications, UOMs, GST rates, payment terms, transport modes, warehouses, etc.)<br>' +
        '&bull; All audit trail, custom reports, and saved drafts<br>' +
        '&bull; Company Details, Login Page slides, Menu Management settings<br>' +
        '<br><b>This will preserve:</b> the default Admin user (so you can log in again).' +
      '</div>',
    confirmText: 'Yes, clear everything', danger: true,
    onConfirm: function () {
      // v5: capture the current admin user (and any other users) so we can
      // restore them on top of the freshly-built defaultDB
      const preservedUsers = (db.users || []).slice();
      // also preserve the currently logged-in user's id so they stay signed in
      const preservedUserId = (function () { try { return sessionStorage.getItem('stitchflow_user_id') || ''; } catch (e) { return ''; } })();
      db = defaultDB();
      db.users = preservedUsers;            // keep everyone (admin, manager, store)
      // do NOT clear sessionStorage here — that would log the user out.
      // drafts in sessionStorage are harmless and will be cleared naturally
      // when the user opens a new form.
      saveDB();
      // reset the entire app state and go to a clean dashboard
      pageView = null; cur = 'dashboard'; mTab = 'items'; mPage = 1; mSize = 25; mQuery = '';
      // restore the login session in case saveDB blew it away
      try { if (preservedUserId) sessionStorage.setItem('stitchflow_user_id', preservedUserId); } catch (e) {}
      toast('All data cleared — every record and master removed', 'red');
      render();
    }
  });
}


/* =====================================================================
   COSTING — buyer order costing (fabric + trims BOM, cost break-up, FOB)
   ===================================================================== */
const fmt2 = (n) => (Number(n)||0).toFixed(2);
const fmt4 = (n) => (Number(n)||0).toFixed(4);

const COST_ROWS = [
  {id:'fabric',        label:'Fabric Cost',        type:'auto'},
  {id:'trims',         label:'Trims Cost',         type:'auto'},
  {id:'cm',            label:'CM *',               type:'cost', def:0},
  {id:'washing',       label:'Washing',            type:'cost', def:0},
  {id:'photoshoot',    label:'Photoshoot',         type:'cost', def:0},
  {id:'transportation',label:'Transportation',     type:'cost', def:0},
  {id:'testing',       label:'Testing',            type:'cost', def:0},
  {id:'totalMaking',   label:'Total making cost with fabric and trims', type:'auto', strong:true},
  {id:'garmentRejection', label:'Garment Rejection *', type:'pct', def:0},
  {id:'finance',       label:'Finance *',          type:'pct', def:0},
  {id:'totalProduction', label:'Total Production Cost', type:'auto', strong:true},
  {id:'cogs',           label:'COGS',              type:'auto'},
  {id:'margin',         label:'Margin',            type:'auto'},
  {id:'cmp',            label:'CMP',               type:'auto', strong:true}
];

function costRemoveRow(btn, tbodyId) {
  const tb = $(tbodyId);
  if (!tb) return;
  if (tb.querySelectorAll('tr').length <= 1) { toast('At least one row needed', 'red'); return; }
  btn.closest('tr').remove();
  renumberSr(tb);
  recalcAll();
}
function costNumVal(v) { return (v === undefined || v === null || v === '') ? '' : v; }
function costItemRow(tbodyId, item, cons, uom, rate, wastage) {
  const uomId = rid('cuom');
  return '<tr>' +
    '<td class="sr-cell" data-sr></td>' +
    '<td><input class="inp" data-f="item" placeholder="Particulars" value="' + esc(item||'') + '"></td>' +
    '<td><input class="inp num" type="number" step="any" data-f="cons" value="' + costNumVal(cons) + '" oninput="recalcAll()"></td>' +
    '<td>' + cbox(uomId, { opts: db.masters.uoms || [], value: uom || '', f:'uom', placeholder:'UOM', compact:true }) + '</td>' +
    '<td><input class="inp num" type="number" step="any" data-f="rate" value="' + costNumVal(rate) + '" oninput="recalcAll()"></td>' +
    '<td><input class="inp num" type="number" step="any" data-f="wastage" value="' + costNumVal(wastage) + '" oninput="recalcAll()"></td>' +
    '<td><input class="inp num" data-f="amount" value="0.0000" readonly tabindex="-1" title="Cons × (1 + Wastage%) × Rate"></td>' +
    '<td class="xl-act"><button type="button" class="btn-icon danger" title="Remove" onclick="costRemoveRow(this,\'' + tbodyId + '\')">' + ic('trash', 14) + '</button></td>' +
  '</tr>';
}
function fabricRowTpl() { return costItemRow('fabricBody'); }
function sewingRowTpl() { return costItemRow('sewingBody'); }

